import{_ as a,o as n,c as s,a5 as i}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"6. Compiling, Linking, and Executing","description":"The Little Book of C — 6. Compiling, Linking, and Executing","frontmatter":{"title":"6. Compiling, Linking, and Executing","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Getting Started"],"description":"The Little Book of C — 6. Compiling, Linking, and Executing","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":6,"sidebarWeight":6,"lang":"en-US","alternateEn":"/posts/c教程/en-US/01-Getting Started/006-Compiling, Linking, and Executing","alternateZh":"/posts/c教程/zh-CN/01-入门/006-Compiling, Linking, and Executing"},"headers":[],"relativePath":"posts/c教程/en-US/01-Getting Started/006-Compiling, Linking, and Executing.md","filePath":"posts/c教程/en-US/01-Getting Started/006-Compiling, Linking, and Executing.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/en-US/01-Getting Started/006-Compiling, Linking, and Executing.md"};function o(p,e,l,c,d,r){return n(),s("div",null,[...e[0]||(e[0]=[i(`<p>[中文版本](/posts/c教程/zh-CN/01-入门/006-Compiling, Linking, and Executing)</p><p>When you press Enter to compile your C program, a lot happens behind the scenes. Your source code goes through several stages before it becomes a runnable executable. Understanding these steps is essential, it turns compilation errors from mysteries into simple, fixable clues.</p><h4 id="tiny-code" tabindex="-1">Tiny Code <a class="header-anchor" href="#tiny-code" aria-label="Permalink to &quot;Tiny Code&quot;">​</a></h4><p>Let’s start with a familiar program:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Learning the C build process!\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Now compile and run it step by step:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Step 1: Compile to object file</span></span>
<span class="line"><span>gcc -c hello.c -o hello.o</span></span>
<span class="line"><span># Step 2: Link object file into executable</span></span>
<span class="line"><span>gcc hello.o -o hello</span></span>
<span class="line"><span># Step 3: Run the program</span></span>
<span class="line"><span>./hello</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Learning the C build process!</span></span></code></pre></div><h4 id="the-four-stages-of-building-a-c-program" tabindex="-1">The Four Stages of Building a C Program <a class="header-anchor" href="#the-four-stages-of-building-a-c-program" aria-label="Permalink to &quot;The Four Stages of Building a C Program&quot;">​</a></h4><p>Preprocessing The preprocessor handles all lines starting with<code>#</code>. It expands macros, includes headers, and prepares code for compilation. Command to inspect:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -E hello.c | less</span></span></code></pre></div><p>Compilation The compiler translates the preprocessed code into assembly language, and then into object code. Each source file (like<code>hello.c</code>) becomes an object file (<code>hello.o</code>). Command:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c hello.c</span></span></code></pre></div><p>Linking The linker combines all object files and libraries into one final executable. For example,<code>printf</code> comes from the C standard library (<code>libc</code>), so the linker connects your code to it. Command:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc hello.o -o hello</span></span></code></pre></div><p>Execution Once linked, your binary (<code>hello</code>) is loaded by the operating system and executed by the CPU. Command:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./hello</span></span></code></pre></div><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>C gives you control over every stage of this process. Most modern languages hide compilation or linking, but in C, these steps are transparent and configurable. When something goes wrong, a missing function, an undefined symbol, or a broken include, you’ll know exactly which stage to look at.</p><p>Mastering the build process also opens the door to deeper skills:</p><ul><li>Creating reusable libraries (<code>.a</code> or<code>.so</code> files)</li><li>Understanding Makefiles and build automation</li><li>Debugging with symbols and optimized builds</li><li>Writing portable programs that compile cleanly anywhere</li></ul><p>Every system programmer eventually learns to think like a compiler, and this is where that thinking begins.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><p>Experiment with separate compilation:</p><p>Create two files:</p><p>main.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>void greet(void);</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    greet();</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>greet.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>void greet(void) {</span></span>
<span class="line"><span>    printf(&quot;Hello from another file!\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Then compile and link:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c main.c</span></span>
<span class="line"><span>gcc -c greet.c</span></span>
<span class="line"><span>gcc main.o greet.o -o greetprog</span></span>
<span class="line"><span>./greetprog</span></span></code></pre></div><p>Try breaking it: Delete the<code>void greet(void);</code> line in<code>main.c</code> and recompile, see how the compiler warns you about an implicit declaration.</p><p>Observe the stages: Add flags like<code>-Wall -O2 -v</code> to see detailed messages from the compiler and linker.</p><p>Once you understand compilation and linking, you’ve unlocked one of the most powerful parts of C, the ability to control exactly how your software is built, combined, and executed.</p>`,35)])])}const u=a(t,[["render",o]]);export{h as __pageData,u as default};
